def meta(s):return {k[3:]:getattr(s,k) for k in FIELDS}
def read(path,limit=32*1024**2):
 path=Path(path);fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
 with os.fdopen(fd,'rb') as f:
  before=meta(os.fstat(f.fileno()));require(stat.S_ISREG(before['mode']) and before['nlink']==1 and before['size']<=limit,'independent bounded regular file required')
  raw=f.read();require(len(raw)==before['size'] and before==meta(os.fstat(f.fileno()))==meta(path.lstat()),'same-descriptor input changed')
