def outer(pin,expected):
 doc=json.loads(checked(pin,2*1024**2));require(doc['schema']=='hepta.rea.c2.archive.literal-outer.v1' and doc['launch_api']=='process_start','exact original API/schema differs')
 require(doc['launch_request']==expected,'actual request/budgets differ')
 start=doc['start'];j=start['job'];s=doc['status']
 require(start['launch']['ok'] and not start['reused'] and j['execution_mode']=='operator' and j['env_keys']==[],'admission identity differs')
 for key in ('host','executable','args','cwd','idempotency_key'):require(j[key]==expected[key],'original job '+key+' differs')
 require(j['launch_state']=='launched' and j['launch_error'] is None,'original launch incomplete')
 require(s['job_id']==j['id'] and s['state']=='succeeded' and s['exit_code']==0 and s['output_complete'] and s['output_durable'] and s['terminal_publication_confirmed'],'original owner terminal not complete')
 require(not s['automatic_retry'] and not s['cancelled'] and not s['timed_out'],'unexpected retry/cancel/timeout')
 streams={'stdout':bytearray(),'stderr':bytearray()}
 require(doc['reads'],'original raw pages missing')
 for page in doc['reads']:
  req,r=page['request'],page['response'];require(req['host']==expected['host'] and req['job_id']==r['job_id']==j['id'],'original raw page identity differs')
  require(type(req['limit']) is int and 1<=req['limit']<=16384,'raw page limit differs')
  for name,out in streams.items():
   item=r[name];block=bytes.fromhex(item['bytes_hex']);before=len(out)
   require(req[name+'_offset']==item['offset']==before and item['next_offset']==before+len(block) and len(block)<=req['limit'],'raw cursor differs')
   out.extend(block)
 for name,out in streams.items():
  last=doc['reads'][-1]['response'][name]
  require(last['eof'] and last['size']==last['next_offset']==len(out) and s['log_bytes'][name]=={'seen':len(out),'stored':len(out)} and s['log_synced'][name] and not s['log_truncated'][name] and s['log_errors'][name] is None,'original stream not complete and durable')
 require(not streams['stderr'] and streams['stdout'].count(b'\n')==1,'one success JSON line required')
 return json.loads(bytes(streams['stdout'])),{'literal_outer':pin,'job_id':j['id'],'state':s['state'],'exit_code':0,'output_complete':True,'output_durable':True,'terminal_publication_confirmed':True,'stdout_bytes':len(streams['stdout']),'stderr_bytes':0}
def identity(path):
 path=Path(path);fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
 h=hashlib.sha256();count=0
 with os.fdopen(fd,'rb') as f:
  before=meta(os.fstat(f.fileno()));require(stat.S_ISREG(before['mode']) and before['nlink']==1,'delivery regular single-link file required')
  for block in iter(lambda:f.read(1024*1024),b''):count+=len(block);h.update(block)
  require(count==before['size'] and before==meta(os.fstat(f.fileno()))==meta(path.lstat()),'delivery input changed')
 return {'relative_path':path.relative_to(D).as_posix(),'bytes':count,'sha256':h.hexdigest()},before
def enumerate_files():
 out=[];dirs=[]
 for directory,children,names in os.walk(D,followlinks=False):
  directory=Path(directory);require(not directory.is_symlink(),'delivery symlink directory forbidden')
  dirs.append(directory.relative_to(D).as_posix())
  for child in children:require(not (directory/child).is_symlink(),'delivery symlink forbidden')
  out.extend(directory/name for name in names)
 return sorted(out),sorted(dirs)
